return {
  name: node.properties.toolName?.value || 'web_search',
  description: node.properties.toolDescription?.value || 'Search the web',
  enabled: node.properties.enabled?.value !== false,
  schema: {
    type: 'object',
    properties: {
      query: {
        type: 'string',
        description: 'The search query'
      },
      maxResults: {
        type: 'number',
        description: 'Maximum number of results (default: 5)'
      }
    },
    required: ['query']
  },
  code: `const fetch = (await import('node-fetch')).default;
const maxResults = args.maxResults || 5;
const url = \`https://html.duckduckgo.com/html/?q=\${encodeURIComponent(args.query)}\`;
const response = await fetch(url, {
  headers: {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
  }
});
const html = await response.text();
const cheerio = require('cheerio');
const $ = cheerio.load(html);
const results = [];
$('.result__body').slice(0, maxResults).each((i, el) => {
  const title = $(el).find('.result__title').text().trim();
  const snippet = $(el).find('.result__snippet').text().trim();
  const link = $(el).find('.result__url').attr('href');
  if (title && link) {
    results.push({ title, snippet, url: link });
  }
});
return { query: args.query, results, count: results.length };`
};
